// Üretilen dosya: tool/ozgun/uret.py. Yabancı Dil · Dilbilim temel kavramları: ses bilgisi, anlam bilim, dil aileleri (kolay).
const ozLanguage12Kolay = <(String, String, List<String>, String)>[
  ('Konuşma seslerinin ağız, dil ve dudaklar gibi organlarla nasıl üretildiğini inceleyen ses bilgisi dalı hangisidir?', 'boğumlanma ses bilgisi (artikülatör fonetik)', ['akustik ses bilgisi (fizik temelli)', 'işitsel ses bilgisi (algı temelli)', 'tarihsel ses bilgisi'], 'Seslerin üretim sürecini, yani hangi organın nerede ve nasıl engel oluşturduğunu boğumlanma (artikülatör) ses bilgisi inceler.'),
  ('Bir araştırmacı, konuşma seslerinin havada yayılan dalgalar olarak sıklık, genlik ve süre gibi fiziksel özelliklerini ölçüyor. Bu araştırmacı ses bilgisinin hangi dalında çalışmaktadır?', 'akustik ses bilgisi', ['boğumlanma ses bilgisi', 'işitsel ses bilgisi', 'biçim bilgisi'], 'Sesin fiziksel dalga özelliklerini inceleyen dal akustik ses bilgisidir.'),
  ('Kulağın ve beynin konuşma seslerini nasıl algıladığını, örneğin iki sesin hangi noktada farklı duyulmaya başladığını inceleyen dal hangisidir?', 'işitsel ses bilgisi', ['akustik ses bilgisi', 'boğumlanma ses bilgisi', 'anlam bilim'], 'Seslerin dinleyici tarafından algılanmasını işitsel (algısal) ses bilgisi inceler.'),
  ('Üst ön dişlerin hemen arkasında, damağın başladığı yerdeki kabarık bölgeye ses bilgisinde ne ad verilir?', 'alveol', ['yumuşak damak', 'küçük dil', 'gırtlak kapağı'], 'Türkçedeki t, d, n, s gibi seslerin çoğu dilin ucu bu çıkıntıya yaklaştırılarak üretilir; bu bölgeye alveol denir.'),
  ('Konuşma seslerinin büyük çoğunluğunu oluşturan hava akımı hangi organdan kaynaklanır?', 'akciğerler', ['mide', 'burun boşluğu', 'gırtlak kapağı'], 'Dünya dillerindeki seslerin büyük kısmı akciğerden dışarı itilen havayla üretilir; bu akıma akciğer kaynaklı hava akımı denir.'),
  ('Parmaklarınızı boğazınıza koyup önce uzun bir "sss", sonra uzun bir "zzz" sesi çıkardığınızda yalnız ikincisinde titreşim hissedersiniz. Bu fark neyi gösterir?', 'z\'nin ötümlü, s\'nin ötümsüz olduğunu', ['s sesinin aslında genizsil olduğunu', 'z sesinin patlamalı bir ses olduğunu', 'İki sesin farklı yerde boğumlandığını'], 's ile z aynı yerde ve aynı biçimde boğumlanır; tek farkları z üretilirken ses tellerinin titreşmesidir.'),
  ('Aşağıdaki ses çiftlerinin hangisinde iki ses yalnız ötümlülük bakımından birbirinden ayrılır?', 'f – v', ['m – b', 's – ş', 'k – t'], 'f ve v ikisi de dudak-diş sürtünmelisidir; v ötümlü, f ötümsüzdür. Öteki çiftlerde boğumlanma yeri ya da biçimi de değişir.'),
  ('Bir dil bilimci bir dildeki bütün ünsüzleri iki gruba ayırıyor: üretilirken ses tellerinin titreştiği ve titremediği ünsüzler. Bu sınıflandırmanın ölçütü hangisidir?', 'ötümlülük', ['boğumlanma yeri', 'genizsillik', 'uzunluk'], 'Ünsüzlerin ses tellerinin titreşip titreşmemesine göre ayrılması ötümlülük ölçütüdür; ötümlü ve ötümsüz ünsüzler bu yolla belirlenir.'),
  ('Aşağıdaki İngilizce sözcük çiftlerinden hangisi yalnız ilk sesin ötümlülüğüyle anlam ayrımı yapar?', 'pin – bin', ['pin – tin', 'pin – pan', 'pin – fin'], 'p ve b aynı yerde aynı biçimde boğumlanır; ayrımı yalnız ötümlülük sağlar. Öteki çiftlerde yer, biçim ya da ünlü değişmiştir.'),
  ('İki dudağın birbirine değmesi ya da yaklaşmasıyla üretilen [p], [b] ve [m] seslerinin boğumlanma yeri hangisidir?', 'çift dudak', ['dudak-diş', 'diş eti', 'art damak'], 'p, b ve m iki dudağın kapanmasıyla oluşur; bu seslere çift dudak (bilabial) sesleri denir.'),
  ('[f] ve [v] sesleri üretilirken hangi organlar birbirine yaklaşır?', 'alt dudak ile üst ön dişler', ['iki dudak', 'dil ucu ile diş eti çıkıntısı', 'dil sırtı ile yumuşak damak'], 'f ve v dudak-diş (labiodental) sesleridir: alt dudak üst dişlere yaklaşır ve hava aradan sürtünerek geçer.'),
  ('Ses yolunda havanın akışının bir an tamamen kesilip sonra birden bırakılmasıyla oluşan ünsüzlere ne ad verilir?', 'patlamalı ünsüzler', ['sürtünmeli ünsüzler', 'yarı ünlüler', 'yan (lateral) ünsüzler'], 'Havanın tamamen tutulup ani salıverilmesiyle p, t, k, b, d, g gibi patlamalı ünsüzler oluşur.'),
  ('Havanın iki organ arasında oluşan dar bir aralıktan sürtünerek geçmesiyle üretilen ünsüzlere ne ad verilir?', 'sürtünmeli ünsüzler', ['patlamalı ünsüzler', 'genizsil ünsüzler', 'çarpmalı (tek vuruşlu) ünsüzler'], 's, z, ş, f, v gibi sesler daralan bir aralıkta havanın sürtünmesiyle oluşur; bunlar sürtünmeli (frikatif) ünsüzlerdir.'),
  ('Bir ünsüzü ses bilgisinde tam olarak betimlemek için genellikle hangi üç özellik birlikte verilir?', 'ötümlülük, yer ve biçim', ['uzunluk, vurgu ve ton', 'hece sayısı, yazım ve köken', 'yuvarlaklık, yükseklik ve öne-arkalık'], 'Örneğin [d] ötümlü, diş eti, patlamalı bir ünsüz olarak betimlenir; bu üç özellik ünsüz betimlemesinin temelidir.'),
  ('"Ötümlü, çift dudak, genizsil" betimlemesine uyan ses hangisidir?', '[m]', ['[n]', '[b]', '[p] ya da [pʰ]'], '[m] iki dudak kapanıp hava burundan çıkarken ses telleri titreşerek üretilir.'),
  ('Ses bilgisinde ünlüler sınıflandırılırken kullanılan üç temel ölçüt hangileridir?', 'dil yüksekliği, öne-arkalık, yuvarlaklık', ['ötümlülük, genizsillik, uzunluk', 'boğumlanma yeri, boğumlanma biçimi, ötümlülük', 'vurgu, ton, tonlama'], 'Ünlüler dilin ne kadar yükseldiği, ağzın önünde mi arkasında mı olduğu ve dudakların yuvarlak olup olmadığına göre betimlenir.'),
  ('[i] ile [a] ünlüleri söylenirken ağız açıklığı ve dilin yüksekliği bakımından nasıl bir fark vardır?', '[i]\'de dil yüksek, [a]\'da alçaktır.', ['[i]\'de ağız geniş, [a]\'da ağız dardır.', 'İkisinde de dil aynı yükseklikte kalır.', '[i]\'de dudaklar yuvarlak, [a]\'da düzdür.'], '[i] yüksek (kapalı) bir ön ünlü, [a] alçak (açık) bir ünlüdür; ağız açıklığı dilin yüksekliğiyle ters orantılı değişir.'),
  ('Uluslararası Ses Abecesi\'nin (IPA) temel amacı hangisidir?', 'Her sesi tek ve tutarlı bir simgeyle göstermek', ['Bütün dilleri ortak bir alfabeyle yazmayı zorunlu kılmak', 'Yalnız Avrupa dillerinin yazımını birleştirmek', 'Dillerin anlam ilişkilerini çizelgelemek'], 'IPA\'da her simge tek bir sesi, her ses tek bir simgeyi gösterir; böylece farklı dillerin söyleyişi tutarlı biçimde yazıya geçirilebilir.'),
  ('IPA\'da bir ünlünün ardından gelen [ː] işareti neyi gösterir?', 'sesin uzun söylendiğini', ['sesin genizsil olduğunu', 'sesin vurgulu olduğunu', 'sesin ötümsüz söylendiğini'], '[aː] gibi gösterimlerde iki nokta benzeri işaret ünlünün uzun okunduğunu belirtir.'),
  ('Bir dilde anlam ayırt etme gücü olan en küçük ses birimine ne ad verilir?', 'ses birim (fonem)', ['biçim birim (morfem)', 'hece', 'değişke (alofon)'], 'Fonem, tek başına anlamı olmayan ama yer değiştirdiğinde sözcüğün anlamını değiştiren en küçük ses birimidir.'),
  ('Tek bir ses dışında tamamen aynı olan ve bu tek fark nedeniyle farklı anlamlar taşıyan sözcük çiftine ne ad verilir?', 'en küçük çift', ['eş sesli çift', 'soydaş çift', 'yalancı eş'], '"kar – kır" gibi en küçük çiftler, farklı olan iki sesin o dilde ayrı fonemler olduğunu kanıtlamak için kullanılır.'),
  ('Aşağıdaki Türkçe sözcük çiftlerinden hangisi /b/ ile /p/ seslerinin ayrı ses birimleri olduğunu kanıtlayan bir en küçük çifttir?', 'bul – pul', ['bal – kal', 'kar – kır', 'dal – dil – del'], '"bul" ile "pul" yalnız ilk seste ayrılır ve anlamları farklıdır; bu, b ile p\'nin ayrı fonem olduğunu gösterir.'),
  ('Aynı ses birimin, çevresindeki seslere göre farklı biçimlerde söylenen ama anlam ayırt etmeyen gerçekleşmelerine ne ad verilir?', 'değişke', ['en küçük çift', 'biçim birim', 'ikiz ünlü'], 'Örneğin Türkçede /k/ ses biriminin "kır"daki art ve "kir"deki ön damak söyleyişleri aynı fonemin değişkeleridir.'),
  ('Ses bilgisinde bir hecenin zorunlu öğesi olan ve çoğu dilde bir ünlünün oluşturduğu bölüme ne ad verilir?', 'çekirdek', ['ilk ses öbeği', 'kod', 'kafiye kökü ve ek'], 'Hece; isteğe bağlı başlangıç (onset), zorunlu çekirdek ve isteğe bağlı koddan oluşur. Çekirdek genellikle ünlüdür.'),
  ('Ünlüyle biten hecelere ne ad verilir?', 'açık hece', ['kapalı hece', 'ağır hece', 'vurgulu hece'], 'Sonunda ünsüz bulunmayan, ünlüyle biten heceler açık hece; ünsüzle bitenler kapalı hecedir.'),
  ('Sözcüğün bir hecesinin ötekilerden daha güçlü, daha yüksek ya da daha uzun söylenmesine ne ad verilir?', 'vurgu', ['tonlama', 'ulama', 'ses uyumu'], 'Vurgu, bir hecenin ses şiddeti, perde ve süre bakımından öne çıkarılmasıdır.'),
  ('Ton dilleri hakkında hangisi doğrudur?', 'Hecenin ses perdesi sözcüğün anlamını değiştirebilir.', ['Sözcüklerin anlamı yalnızca vurguyla değişir.', 'Ses perdesi yalnızca duyguyu gösterir, anlam ayırt etmez.', 'Bu dillerde ünlü bulunmaz, yalnızca ünsüz vardır.'], 'Ton dillerinde perde, sözcük düzeyinde anlam ayırt eden bir özelliktir; aynı hece farklı tonlarla farklı sözcüklere dönüşür.'),
  ('Sözcük düzeyinde değil cümle düzeyinde ses perdesinin yükselip alçalmasına ne ad verilir?', 'tonlama (ezgi)', ['ton (sözcük perdesi)', 'vurgu', 'ses uyumu'], 'Tonlama; soru, bildirme, şaşırma gibi anlamları cümlenin genel ezgisiyle gösterir.'),
  ('"Geliyor." ile "Geliyor?" cümlelerini konuşmada birbirinden ayıran temel özellik hangisidir?', 'cümle sonundaki ezginin yükselmesi', ['sözcüğün farklı ünlülerle söylenmesi', 'sözcüğe yeni bir ek getirilmesi', 'vurgunun ilk heceye kayması'], 'Soru eki olmadan sorulan sorularda cümle sonu ezgisi yükselir; tonlama bu iki cümleyi ayırır.'),
  ('"Bugün okula ALİ geldi." cümlesinde büyük harfle yazılan sözcüğün güçlü söylenmesi dinleyiciye en çok hangi bilgiyi verir?', 'Gelenin başkası değil Ali olduğunu', ['Ali\'nin okula her gün geldiğini', 'Cümlenin bir soru olduğunu', 'Ali\'nin okula yürüyerek geldiğini'], 'Cümle vurgusu, konuşanın öne çıkarmak istediği öğeyi işaretler; burada yeni ve önemli bilgi kişinin kimliğidir.'),
  ('İngilizce "family" sözcüğünün hızlı konuşmada "fam\'ly" diye iki heceyle söylenmesi hangi süreçtir?', 'ünlü düşmesi', ['ünlü türemesi', 'aykırılaşma', 'ünlü uzaması'], 'Vurgusuz bir ünlünün söylenmemesi ünlü düşmesidir (senkop).'),
  ('Ses şiddetini ölçmek için kullanılan birim hangisidir?', 'desibel', ['hertz', 'mora', 'milisaniye'], 'Sesin şiddeti ya da yüksekliği desibelle ölçülür; hertz ise sıklık birimidir.'),
  ('Dünya dillerinde en yaygın olan hava akımı hangisidir?', 'akciğerden dışarı akan hava', ['gırtlaktan içeri çekilen hava', 'dil sırtıyla içeri emilen hava', 'burundan içeri çekilen hava'], 'Bütün dillerde seslerin çoğu akciğerden dışarı verilen havayla üretilir; ejektif, implozif ve tık sesleri daha az görülen akımlara dayanır.'),
  ('Bir hece içinde dilin bir ünlü konumundan ötekine kayarak geçtiği tek çekirdekli ünlüye ne ad verilir?', 'diftong', ['uzun ünlü', 'genizsil ünlü', 'şva'], 'İngilizce "eye" sözcüğündeki [aɪ] gibi, tek hecede bir ünlüden başka bir ünlüye kayan seslere diftong denir.'),
  ('Doğadaki sesleri taklit eden sözcüklerin farklı dillerde birbirinden ayrılması, örneğin horoz sesinin Türkçede "üürü üüü", İngilizcede "cock-a-doodle-doo", Fransızcada "cocorico" olması neyi gösterir?', 'Yansımaların da dilin ses dizgesine uyduğunu', ['Horozların ülkeden ülkeye farklı biçimde öttüğünü', 'Yansımaların bütün dillerde aynı biçimde yazıldığını', 'Yansıma sözcüklerin hiçbir dilde bulunmadığını'], 'Yansımalar doğal sesi taklit etse de her dil bunu kendi ses birimleri ve hece kalıplarıyla yapar; bu nedenle tam olarak aynı olmazlar.'),
  ('"Burası biraz soğuk, değil mi?" diyen bir konuğun aslında pencerenin kapatılmasını istemesi dil biliminin hangi dalının konusudur?', 'edim bilim (pragmatik)', ['ses bilim (fonoloji)', 'biçim bilim', 'sözdizimi'], 'Bir sözün bağlam içinde konuşanın amacına göre kazandığı anlam edim bilimin konusudur; sözcüklerin sözlük anlamı ise anlam bilimle incelenir.'),
  ('Saussure\'e göre dilsel gösterge hangi iki öğeden oluşur?', 'gösteren ve gösterilen', ['ses ve harf', 'sözcük ve cümle', 'konuşan ve dinleyen kişi'], 'Saussure\'e göre gösteren, sesin zihindeki imgesidir; gösterilen ise bu imgeyle bağlanan kavramdır.'),
  ('Bir sözcüğün sözlükteki temel, nesnel anlamına ne ad verilir?', 'düz anlam', ['yan anlam', 'mecaz anlam', 'terim anlam'], 'Düz anlam (denotasyon), sözcüğün gösterdiği varlık ya da kavramı nesnel olarak belirten anlamdır.'),
  ('"Ev" ile "yuva" aynı yapıyı gösterebilir; ama "yuva" sözcüğü sıcaklık ve aile duygusu da çağrıştırır. Bu ek çağrışıma ne ad verilir?', 'yan anlam', ['düz anlam', 'terim anlamı', 'gerçek anlam'], 'Yan anlam (konotasyon), sözcüğün düz anlamına eklenen duygusal ve kültürel çağrışımlardır.'),
  ('"Sıcak – soğuk" çiftinde "ılık" ve "serin" gibi ara dereceler bulunur ve "çok sıcak" denebilir. Bu tür karşıt anlamlılığa ne ad verilir?', 'derecelenebilir karşıtlık', ['tamamlayıcı karşıtlık', 'karşılıklı (ters yönlü) karşıtlık', 'eş seslilik'], 'Derecelenebilir karşıtlarda iki uç arasında bir ölçek vardır; birinin olumsuzu ötekini zorunlu kılmaz.'),
  ('"Lale" ile "çiçek" arasındaki ilişkide "lale" hangi konumdadır?', 'alt anlamlı', ['üst anlamlı', 'eş anlamlı', 'karşıt anlamlı'], 'Her lale bir çiçektir ama her çiçek lale değildir; dar kavram olan "lale" alt anlamlı, geniş kavram olan "çiçek" üst anlamlıdır.'),
  ('Aşağıdakilerin hangisinde ilk sözcük ikincinin üst anlamlısıdır?', 'mobilya – sandalye', ['sandalye – mobilya', 'sandalye – koltuk', 'sandalye – sandalye ayağı'], 'Mobilya sandalyeyi de kapsayan genel kavramdır; sandalye mobilyanın bir türüdür.'),
  ('Aşağıdaki çiftlerden hangisinde parça-bütün ilişkisi vardır?', 'sayfa – kitap', ['roman – kitap', 'kitap – dergi', 'kitap – okumak'], 'Sayfa kitabın bir parçasıdır; "roman – kitap" ise tür ilişkisidir.'),
  ('Bir sözcüğün birbiriyle ilişkili birden çok anlam taşımasına ne ad verilir?', 'çok anlamlılık', ['eş seslilik', 'eş anlamlılık', 'karşıt anlamlılık'], '"Ağız" sözcüğünün insan ağzı, şişe ağzı, nehir ağzı anlamları gibi birbirine bağlı anlamlar çok anlamlılığı (polisemi) oluşturur.'),
  ('"Yüz" sözcüğü hem 100 sayısını hem de insanın çehresini anlatır. Bu iki anlam arasında hiçbir ilişki yoktur. Bu durum hangi kavramla açıklanır?', 'eş seslilik', ['çok anlamlılık', 'alt anlamlılık', 'yan anlam'], 'Aynı biçimde olan ama anlamları arasında bağ bulunmayan sözcükler eş seslidir (homonim); sözlüklerde genellikle ayrı maddeler olarak verilir.'),
  ('İngilizce "night" ile "knight" sözcüklerinin ilişkisi nasıl adlandırılır?', 'Söyleyişleri aynı, yazımları farklıdır.', ['Yazımları aynı, söyleyişleri farklıdır.', 'Hem yazımları hem söyleyişleri farklıdır.', 'Aynı sözcüğün iki anlamıdır.'], 'İkisi de [naɪt] diye söylenir ama farklı yazılır; bunlar eş sesli (homofon) sözcüklerdir.'),
  ('İngilizce "dog" sözcüğü Orta İngilizcede belirli bir köpek cinsini anlatırken bugün bütün köpekleri kapsar. Bu tür anlam değişmesine ne ad verilir?', 'anlam genişlemesi', ['anlam daralması', 'anlam kötüleşmesi', 'anlam iyileşmesi'], 'Sözcüğün önceden dar bir kavramı anlatırken daha geniş bir kavramı kapsar hâle gelmesi anlam genişlemesidir.'),
  ('Bilgisayar alanında "fare", "pencere", "virüs" sözcüklerinin yeni anlamlar kazanması hangi anlam değişmesi nedenine örnektir?', 'Yeni kavramların adlandırılma gereksinimi', ['Sözcüklerin ses yapısının bozulması', 'Tabu nedeniyle sözcüklerden kaçınılması', 'Sözcüklerin unutulmaya yüz tutması'], 'Teknolojik yenilikler mevcut sözcüklerin benzerlik yoluyla yeni kavramlara aktarılmasına yol açar.'),
  ('Bir sözcüğün benzerlik ilişkisiyle başka bir kavramın yerine kullanılmasına ne ad verilir? Örnek: "Sınıfımızın aslanı Mert bugün yine sahadaydı."', 'eğretileme (metafor)', ['ad aktarması (metonimi)', 'örtmece', 'yansıma'], 'Mert\'in cesareti ile aslan arasında benzerlik kurulmuştur; benzerliğe dayanan aktarma eğretilemedir.'),
  ('"Shakespeare okumayı severim." cümlesinde yazar adının eserleri yerine kullanılması hangi ilişkiye dayanır?', 'yazar – eser ilişkisine', ['benzerlik ilişkisine', 'karşıtlık ilişkisine', 'eş seslilik ilişkisine dayanan'], 'Yazar adı ile eserleri arasındaki ilişki ad aktarmasının yaygın türlerinden biridir.'),
  ('Kötü, ayıp ya da korkutucu sayılan bir şeyi daha yumuşak bir ifadeyle anlatmaya ne ad verilir? Örnek: "öldü" yerine "aramızdan ayrıldı" demek.', 'örtmece (eufemizm)', ['kaba söz (disfemizm)', 'eğretileme', 'abartma'], 'Örtmece, hoş karşılanmayan ya da üzücü bir kavramı daha nazik bir dille anlatmaktır.'),
  ('Bir şirketin işçi çıkarmayı "yeniden yapılanma" ya da "küçülmeye gitme" diye duyurması hangi dil kullanımına örnektir?', 'kurumsal örtmece', ['kaba söz', 'eğretileme kullanmama', 'terim türetme'], 'Olumsuz algılanacak bir uygulamayı yumuşatan sözcük seçimi örtmecedir; kurum dillerinde sık görülür.'),
  ('"Kırmızı, mavi, yeşil, sarı" ya da "amca, dayı, hala, teyze" gibi ortak bir kavram çevresinde toplanan sözcük kümelerine anlam bilimde ne ad verilir?', 'anlamsal alan', ['ses birim kümesi', 'eş sesli küme', 'sözdizim öbeği'], 'Anlamsal alan kuramına göre sözcüklerin anlamı, aynı alandaki öteki sözcüklerle ilişkileri içinde belirlenir.'),
  ('Bileşensel çözümlemede [+İNSAN, −ERKEK, −YETİŞKİN] özellikleriyle betimlenen sözcük hangisidir?', 'kız', ['kadın', 'oğlan', 'adam'], 'Kız; insan, dişil ve yetişkin olmayan bireydir. Kadın yetişkin, oğlan erkektir.'),
  ('Anlam biliminde, "Zeynep kırmızı bir araba aldı." cümlesi doğruysa kesinlikle doğru olması gereken cümle aşağıdakilerden hangisidir?', 'Zeynep bir araba aldı.', ['Zeynep arabayı sattı.', 'Araba çok pahalıydı.', 'Zeynep ilk kez araba aldı.'], 'Bir cümle doğruysa ondan zorunlu olarak çıkan cümleye gerektirilen cümle denir. Kırmızı araba almak, araba almayı gerektirir; diğer seçenekler cümleden çıkmaz.'),
  ('"Ya yarın yağmur yağacak ya da yağmayacak." cümlesi mantık ve anlam biliminde hangi türdendir?', 'totoloji (her koşulda doğru)', ['çelişki (her koşulda yanlış)', 'bireşimsel yanlış', 'ön varsayımlı cümle'], 'Bir önermenin ya kendisi ya da olumsuzu olduğunu söyleyen cümle, dünyadaki duruma bakılmaksızın doğrudur; buna totoloji denir.'),
  ('Aşağıdaki cümlelerden hangisi çelişkidir, yani anlamı gereği hiçbir koşulda doğru olamaz?', 'Dört köşeli bir üçgen çizdim.', ['Bu üçgenin köşeleri çok sivri.', 'Üçgen çizmeyi hiç sevmem.', 'Çizdiğim üçgen kâğıdın ortasında.'], 'Üçgenin tanımı üç köşeliliği içerdiğinden "dört köşeli üçgen" kendi içinde çelişir. Diğerleri dünya bilgisine göre doğru ya da yanlış olabilir.'),
  ('"Bütün bekârlar evli değildir." cümlesinin doğruluğunu anlamak için dünyayı gözlemlemeye gerek yoktur. Bu tür cümlelere ne ad verilir?', 'çözümsel (analitik) cümle', ['bireşimsel (sentetik) cümle', 'edim bilimsel cümle', 'eğretilemeli cümle'], 'Doğruluğu yalnızca sözcüklerin anlamından çıkan cümlelere çözümsel cümle denir. Bireşimsel cümlelerin doğruluğu ise gözlemle belirlenir.'),
  ('"Murat yine geç kaldı." cümlesinin ön varsayımı aşağıdakilerden hangisidir?', 'Murat daha önce de geç kalmıştır.', ['Murat bugün işe gitmemiştir.', 'Murat\'ın saati bozuktur.', 'Murat her gün geç kalır.'], '"Yine" sözcüğü işi daha önce de olduğunu varsaydırır; bu tür sözcüklere ön varsayım tetikleyicisi denir.'),
  ('"Ali, Veli\'den uzundur." cümlesi aşağıdakilerden hangisini gerektirir?', 'Veli, Ali\'den kısadır.', ['Veli, Ali\'den güçlüdür.', 'Ali, Veli\'nin kardeşidir.', 'Veli çok kısadır.'], '"Uzun" ve "kısa" karşıt ilişkide olduğundan karşılaştırmanın yönü değişince cümle aynı durumu anlatır; Veli\'nin Ali\'den kısa olması zorunlu sonuçtur.'),
  ('"Elif, Can\'ın ablasıdır." cümlesinin gerektirdiği bilgi aşağıdakilerden hangisidir?', 'Can\'ın en az bir kardeşi vardır.', ['Can, Elif\'in ablasıdır.', 'Elif ile Can aynı okula gider.', 'Elif, Can\'dan küçüktür.'], 'Abla olmak kardeş olmayı zorunlu kılar. Ablanın kardeşinden büyük olması gerektiğinden "Elif Can\'dan küçüktür" yanlıştır; öteki iki bilgi cümleden çıkmaz.'),
  ('Grice\'ın "işbirliği ilkesi" kapsamındaki dört konuşma ilkesi arasında yer almayan hangisidir?', 'Nezaket', ['Nicelik', 'Nitelik', 'İlişki'], 'Grice\'ın ilkeleri nicelik, nitelik, ilişki ve tarz ilkeleridir. Nezaket ilkesi sonradan Leech gibi araştırmacılar tarafından önerilmiştir.'),
  ('Grice\'a göre "Kanıtı olmayan şeyi söyleme, doğru olduğuna inandığın şeyi söyle." yönergesi hangi ilkedir?', 'Nitelik ilkesi', ['Nicelik ilkesi', 'İlişki ilkesi', 'Tarz ilkesi'], 'Nitelik ilkesi konuşurun doğruluğuna ve kanıta dayanmasını ister; yalan söylemek bu ilkenin ihlalidir.'),
  ('"Açık seçik ol, belirsiz ve muğlak sözlerden kaçın, kısa ve düzenli konuş." yönergesi hangi ilkeye aittir?', 'Tarz', ['Nicelik', 'Nitelik', 'İlişki'], 'Grice\'ın tarz ilkesi, ifadenin nasıl söylendiğiyle ilgilidir: açıklık, kısalık ve düzen.'),
  ('Grice\'ın kuramında bir konuşma ilkesinin, dinleyici fark etsin diye açıkça çiğnenmesine ne denir?', 'ilkeyi alaya almak (flouting)', ['ilkeyi gizlice ihlal etmek (violating)', 'ilkeden vazgeçmek (opting out)', 'ilkeyi çiftlemek'], 'Açıkça çiğnemede konuşur, dinleyicinin farkına varacağını bilir ve bir sezdirim doğurmayı amaçlar. Gizli ihlal ise aldatma amacı taşır.'),
  ('"Bu konuda hiçbir şey söyleyemem." diyen bir tanık, Grice\'ın terimleriyle işbirliği ilkelerine karşı hangi tavrı sergiler?', 'İlkeden açıkça çekilmek', ['İlkeyi gizlice ihlal etmek', 'İlkeyi eğretilemeyle çiğnemek', 'İlkeler arasında çatışma yaşamak'], 'Konuşur işbirliği yapmak istemediğini açıkça belirtir; bu durum ilkelerden çekilme olarak adlandırılır.'),
  ('Grice\'ın işbirliği ilkesi hakkında aşağıdakilerden hangisi doğrudur?', 'Konuşmanın ortak bir amaç doğrultusunda yürüdüğü varsayımına dayanır.', ['Yalnızca yazılı metinlere uygulanır.', 'Doğru bilgi vermeyi değil nazik olmayı hedefler.', 'Dil bilgisi kurallarını açıklar.'], 'İşbirliği ilkesi, katılımcıların konuşmanın amacına uygun katkı sağlayacağını varsayar; sezdirimler bu varsayımdan doğar.'),
  ('İlişki ilkesinin kısa tanımı aşağıdakilerden hangisidir?', 'Konuyla ilgili ol.', ['Doğru olanı söyle.', 'Gerektiği kadar bilgi ver.', 'Açık konuş.'], 'İlişki ilkesi katkının konuşmanın o anki amacıyla ilgili olmasını ister.'),
  ('"Teşekkür ederim." ve "Geçmiş olsun." gibi sözler, Searle\'ün sınıflandırmasında hangi gruba girer?', 'duygu bildirenler', ['bağlayıcılar', 'bildirgeler', 'temsilciler'], 'Duygu bildirenler konuşurun tutum ve duygularını (teşekkür, özür, kutlama, başsağlığı) dile getirir.'),
  ('"Kapıyı kapat!" ve "Lütfen sessiz olun." gibi sözler Searle\'ün söz eylem sınıflandırmasında hangi türdendir?', 'yönlendirici', ['temsilci', 'bağlayıcı', 'bildirge'], 'Yönlendiriciler dinleyiciyi bir şey yapmaya yöneltir: emir, rica, öneri, soru bu gruptadır.'),
  ('"Dünya Güneş\'in çevresinde döner." cümlesi, bir şeyin nasıl olduğunu bildirdiği için Searle\'ün sınıflandırmasında hangi gruba girer?', 'temsilci', ['yönlendirici', 'bağlayıcı', 'bildirge'], 'Temsilciler doğru ya da yanlış olabilen bildirimlerdir: iddia etme, bildirme, betimleme.'),
  ('"Tuzu uzatabilir misin?" sözü biçimce soru olduğu halde çoğunlukla hangi söz eylemi yerine getirir?', 'rica', ['iddia', 'bildirge', 'özür'], 'Biçim ile işlev arasındaki bu ayrılığa dolaylı söz eylem denir. Konuşur soru biçimiyle aslında rica etmektedir.'),
  ('Söylenirken bir eylemin yapıldığını gösteren "lütfen" sözcüğü ya da emir kipi gibi ipuçlarına ne ad verilir?', 'söz içi güç göstergeleri', ['gösterim sözcükleri', 'soydaş sözcükler', 'ses birimler'], 'Söz içi gücü belirlemeye yarayan kip, ton, "lütfen" gibi araçlara güç göstergeleri denir.'),
  ('Anlamı, konuşurun kim olduğuna, nerede ve ne zaman konuştuğuna bağlı olarak belirlenen "ben, burada, şimdi, dün" gibi sözcüklere ne ad verilir?', 'gösterim (deiktik) sözcükleri', ['eş sesli sözcükler', 'soydaş sözcükler', 'yansıma sözcükler'], 'Gösterim sözcükleri kendi başlarına değil, konuşma durumunun kişi, yer ve zaman bilgisiyle yorumlanır.'),
  ('Aşağıdaki sözcüklerden hangisi gösterim sözcüğü sayılmaz?', 'Ankara', ['burada', 'şimdi', 'sen'], '"Ankara" özel addır ve konuşma bağlamı ne olursa olsun aynı yeri gösterir. Ötekilerin gönderimi konuşana ve bağlama göre değişir.'),
  ('Gösterim türlerinin genel sınıflandırmasında hangi üçlü ana gruplar arasında yer alır?', 'kişi, yer, zaman', ['ses, hece, ek', 'ad, sıfat, zarf', 'ton, vurgu, perde'], 'Kişi gösterimi (ben, sen), yer gösterimi (burası, şuradaki) ve zaman gösterimi (şimdi, yarın) temel türlerdir.'),
  ('Gösterim çözümlemesinde "kişi = konuşan, yer = konuşmanın yapıldığı yer, zaman = konuşma anı" üçlüsüne ne ad verilir?', 'gösterim merkezi', ['anlam üçgeni', 'ses dizilimi', 'gösterge zinciri'], 'Bühler\'in kavramı olan origo, gösterimin başlangıç noktasıdır; "bu, şu, ben, şimdi" gibi sözcükler bu merkeze göre yorumlanır.'),
  ('Aşağıdaki ifadelerden hangisi "takvim zamanını" gösterir ve konuşma anına bağlı değildir?', '15 Mart 1999', ['geçen hafta', 'önümüzdeki yıl', 'az önce'], 'Takvim zamanı konuşma anından bağımsız olarak belirli bir tarihi verir. Diğer ifadeler konuşma anına göre yorumlanan gösterim zarflarıdır.'),
  ('Berlin ve Kay\'ın 1969 tarihli çalışmasına göre diller temel renk terimlerini edinirken genel eğilim nasıl işler?', 'Önce koyu-açık ayrımı, sonra kırmızı gibi terimler gelir.', ['Önce mavi, sonra yeşil gelir.', 'Önce kahverengi, sonra siyah gelir.', 'Her dil bütün renk terimlerini aynı anda edinir.'], 'Berlin ve Kay, evrensel bir sıralama saptamıştır: iki terimli sistem (koyu/soğuk, açık/sıcak), sonra kırmızı, sonra yeşil veya sarı gibi.'),
  ('Türkçede "dayı" sözcüğü, bileşensel çözümlemede hangi anlam özellikleriyle tanımlanır?', '[+ERKEK, +ANNE TARAFI, +KARDEŞ]', ['[+ERKEK, +BABA TARAFI, +KARDEŞ]', '[−ERKEK, +ANNE TARAFI, +KARDEŞ]', '[+ERKEK, +ANNE TARAFI, +ÇOCUK]'], 'Dayı, annenin erkek kardeşidir. Amca ise [+ERKEK, +BABA TARAFI, +KARDEŞ] özellikleriyle tanımlanır.'),
  ('Türkçede amca, dayı, hala ve teyze ayrı sözcüklerle ifade edilirken İngilizcede yalnızca "uncle" ve "aunt" bulunur. Bu karşılaştırma neyi gösterir?', 'Akrabalık alanının dillere göre farklı inceliklerde adlandırıldığını', ['İngilizcenin akrabalığı ifade edemediğini', 'Türkçedeki sözcüklerin eş anlamlı olduğunu', 'Akrabalık terimlerinin evrensel olduğunu'], 'Her dil, kültürel önemine göre akrabalık alanını farklı ayrıntıda böler.'),
  ('Sapir–Whorf (dilsel görecelik) kuramının güçlü biçimi ne öne sürer?', 'Dilin, konuşurun düşünce ve algısını belirlediğini', ['Bütün dillerin aynı yapıda olduğunu', 'Düşüncenin dili tamamen belirlediğini', 'Dillerin birbirinden hiç etkilenmediğini'], 'Güçlü görecelik, dilin düşünceyi belirlediğini söyler. Günümüzde genellikle yalnızca zayıf biçimi (dilin düşünceyi etkilediği) kabul görür.'),
  ('Bileşimsellik ilkesine (Frege ilkesi) göre bir bileşik ifadenin anlamı neye dayanır?', 'Parçaların anlamlarına ve bunların birleşme biçimine', ['Yalnızca parçaların sayısına', 'Yalnızca ifadenin sesine', 'Yalnızca konuşurun niyetine'], 'Bu ilke, dilin sınırlı sayıda parçadan sonsuz sayıda yeni cümle kurulup anlaşılmasını açıklar.'),
  ('"Kedi fareyi kovaladı." ile "Fare kediyi kovaladı." cümleleri aynı sözcükleri içerir ama anlamları farklıdır. Bileşimsellik ilkesi bu durumu nasıl açıklar?', 'Anlam, sözcüklerin birleşme biçimine de bağlıdır.', ['Anlam yalnızca sözcüklere bağlıdır.', 'İki cümle eş anlamlıdır.', 'Cümleler çok anlamlıdır.'], 'Bileşimsellikte yalnızca sözcük anlamları değil, bunların dizilişi ve ekler yoluyla kurulan yapı da anlamı belirler.'),
  ('"Ali Ayşe\'yi sevdi." cümlesini anlamak için hangi iki bilgi birlikte gerekir?', 'Sözcüklerin anlamları ve eklerle kurulan sözdizimi', ['Yalnızca sözcüklerin anlamları', 'Yalnızca sözcük sırası', 'Yalnızca konuşurun sesi'], 'Hem "sevmek" gibi sözcüklerin anlamı hem de -yi eki gibi yapı bilgisi gerekir; bileşimselliğin iki ayağı budur.'),
  ('Akraba dillerdeki sözcükler arasında düzenli ses denklikleri arayarak ortak ata dili yeniden kurmaya çalışan yönteme ne ad verilir?', 'karşılaştırmalı yöntem', ['bileşensel çözümleme yöntemi', 'edim çözümlemesi yöntemi', 'söylem çözümlemesi yöntemi'], 'Karşılaştırmalı yöntem, ortak kökenli sözcükler arasındaki sistemli ses denkliklerine dayanarak ata dili yeniden kurar.'),
  ('İngilizce "night", Almanca "Nacht" ve Hollandaca "nacht" sözcüklerinin ortak bir kökten gelmesi bu sözcüklerin dil biliminde hangi adla anılmasını sağlar?', 'soydaş sözcükler', ['eş sesli sözcükler', 'yansıma sözcükler', 'alıntı sözcükler'], 'Ortak bir ata dil sözcüğünden ayrışarak gelişen sözcüklere soydaş (kökteş) sözcük denir.'),
  ('Almanca "Gift" sözcüğü "zehir" anlamına gelirken İngilizce "gift" "armağan" demektir. Bu duruma dil biliminde ne ad verilir?', 'yalancı eş', ['soydaş sözcük çifti', 'ses benzeşmesi olayı', 'eğretileme sanatı'], 'Görünüşleri benzeyen ancak farklı anlam taşıyan sözcük çiftlerine yalancı eş denir. Dil öğrenenler için yanıltıcıdır.'),
  ('Dilbilimde bir sözcüğün başına konan yıldız işareti (örneğin *ph₂tḗr) neyi gösterir?', 'Yeniden kurulmuş, yazılı belgesi olmayan biçimi', ['Yanlış yazılmış biçimi', 'Yansıma olan sözcüğü', 'Alıntı olan sözcüğü'], 'Yıldızlı biçimler, karşılaştırma yoluyla kurulmuş varsayımsal ata dil biçimleridir; doğrudan belgelenmemişlerdir.'),
  ('Soy ağacı modelinin temel varsayımı aşağıdakilerden hangisidir?', 'Ayrılan diller, ayrıldıktan sonra bağımsız gelişir.', ['Diller ayrıldıktan sonra da birbirinden sürekli sözcük alır.', 'Her dil birden çok farklı ata dilden birden türemiştir.', 'Diller zaman içinde hiçbir değişikliğe uğramaz.'], 'Soy ağacı, ayrıldıktan sonra dillerin etkileşmediğini varsayar. Bu varsayım her durumda tutmaz.'),
  ('Bir dil ailesi için çizilen soy ağacında en yukarıda yer alan dile ne ad verilir?', 'ata dil', ['yan dil biçimi', 'alt katman dili', 'yapay dil türü'], 'Soy ağacının kökündeki, kızdil olarak adlandırılan dillerin ortak atasına ata dil denir.'),
  ('Ata dilden ayrılan ve onun gelişmiş bir biçimi olan dillere dil biliminde ne denir?', 'kız diller', ['ata diller', 'yalıtık diller', 'pidgin'], 'Aynı ata dilden türeyen diller, birbirine kardeş dil, ata dile göre ise kız dil olarak adlandırılır.'),
  ('Swadesh listesine "su, el, ben, güneş" gibi sözcükler alınırken "bilgisayar, havaalanı" gibi sözcükler alınmaz. Bunun nedeni nedir?', 'Listedekiler her dilde bulunan, nadiren alıntılanan temel kavramlardır.', ['Bu sözcükler uzun olduğu için ölçüm yapmaya elverişli değildir.', 'Bu sözcükler eş sesli olduğu için hesaplamayı bozar.', 'Bu sözcükler hiçbir dilde yazıya geçirilmediği için'], 'Swadesh listesi, kültüre bağlı olmayan ve alınma ihtimali düşük temel sözcüklerden oluşturulur.'),
  ('Swadesh\'in 100 ya da 200 sözcüklük listeleri dil bilimde ne amaçla kullanılır?', 'Diller arasındaki akrabalık derecesini ve ayrılma zamanını kestirmek için', ['Dillerin ses sayısını bulmak ve karşılaştırmak için', 'Dillerin yazıya geçiş tarihini belirlemek için', 'Şiir ölçüsünü ve uyak düzenini saptamak için'], 'Ortak temel sözcük oranı, iki dilin ne kadar yakın akraba olduğuna dair sayısal bir ölçü verir.'),
  ('Dillerin ayrılma zamanını, ortak temel sözcük oranına bakarak tarihlendirmeye çalışan yönteme ne ad verilir?', 'glottokronoloji', ['sesbirim çözümlemesi', 'söz eylem kuramı', 'anafora çözümlemesi'], 'Glottokronoloji, temel sözcüklerin belirli bir hızla değiştiği varsayımına dayanır. Bu varsayım nedeniyle eleştirilir.'),
  ('Aşağıdaki sözcüklerden hangisinin Swadesh tipi bir temel sözcük listesinde yer alma olasılığı en yüksektir?', 'göz', ['internet', 'televizyon', 'kredi kartı'], 'Vücut parçaları, doğa unsurları ve temel eylem sözcükleri her dilde bulunur ve kültürel alıntıya karşı dirençlidir.'),
  ('İrlandaca, İskoç Galcesi ve Galce (Gal dili) hangi koldan diller sayılır?', 'Kelt kolu', ['Slav kolu', 'Helen kolu', 'Hint-İran kolu'], 'Bu üç dil Britanya Adaları\'ndaki Kelt dilleridir; her biri ortak bir Kelt atasından türemiştir.'),
  ('Romence, İspanyolca, İtalyanca ve Fransızca hangi ortak kaynaktan türemiştir?', 'Halk Latincesi', ['Klasik Eski Yunanca', 'Eski Kilise Slavcası', 'Vedik Sanskritçe'], 'Bu diller Roma İmparatorluğu\'nun konuşulan Latincesinin bölgesel gelişimlerinden doğmuş Romen dilleridir.'),
  ('Gotça adlı ölü dil, Germen kolunun hangi dalına girer?', 'Doğu Germen', ['Batı Germen', 'Kuzey Germen', 'Baltık'], 'Gotça, Wulfila\'nın 4. yüzyılda yaptığı İncil çevirisiyle bilinen Doğu Germen dilidir. Bugün konuşulmamaktadır.'),
  ('Rusça, Ukraynaca ve Belarusça hangi Slav grubunda toplanır?', 'Doğu Slav', ['Batı Slav', 'Güney Slav', 'Baltık'], 'Bu üç dil Doğu Slav grubundadır. Lehçe, Çekçe ve Slovakça Batı Slav; Bulgarca ve Sırpça ise Güney Slav grubundadır.'),
  ('Bulgarca, Sırpça ve Slovence hangi Slav grubuna girer?', 'Güney Slav', ['Doğu Slav grubuna', 'Batı Slav grubuna', 'Baltık grubuna'], 'Balkanlar\'da konuşulan bu diller Güney Slav grubunu oluşturur.'),
  ('Hintçe, Bengalce, Pencapça ve Nepalce hangi Hint-Avrupa kolunun hangi dalındandır?', 'Hint-İran kolunun Hint-Arya dalından', ['Hint-İran kolunun İran dalından', 'Germen kolunun Kuzey dalından', 'Helen kolunun Yunan dalından'], 'Bu diller Sanskritçeden gelişen Hint-Arya dillerindendir.'),
  ('Farsça, Kürtçe ve Peştuca hangi koldan hangi dallara aittir?', 'Hint-İran kolunun İran dalına', ['Hint-İran kolunun Hint-Arya dalına', 'Slav kolunun Güney dalına', 'Germen kolunun Batı dalına'], 'Bu diller Avesta dili ve Eski Farsçayla ortak kökenli olan İran dillerindendir.'),
  ('Çin Türkistanı\'nın (Tarım Havzası) Budist metinlerinde bulunan ve Hint-Avrupa ailesinin en doğudaki kolu sayılan ölü dillere ne ad verilir?', 'Toharca', ['Soğdca', 'Hititçe', 'Avestaca'], 'Toharca A ve B, 6.–8. yüzyıl metinlerinden bilinir; Hint-Avrupa ailesinin Doğu Asya\'daki yayılışının kanıtıdır.'),
  ('Norveççe iki resmî yazı biçimine sahiptir. Bu biçimler hangi adlarla bilinir?', 'Bokmål ve Nynorsk', ['Riksmål ve Kiril', 'Katharevusa ve Dimotiki', 'Ido ve Volapük'], 'Norveç\'te Bokmål (kitap dili) ve Nynorsk (yeni Norveççe) resmî yazı dilleridir.'),
  ('Yunancanın Hint-Avrupa ailesindeki konumu için aşağıdakilerden hangisi doğrudur?', 'Kendi başına bir kol (Helen) oluşturur.', ['Slav kolunun bir alt dalıdır.', 'Germen kolunun bir alt dalıdır.', 'Hint-İran kolunun bir alt dalıdır.'], 'Antik Yunanca ve Modern Yunanca, ailenin Helen kolunu oluşturur; yakın akrabası olmadığı için yalnız başına bir koldur.'),
  ('Danca, Norveççe ve İsveççe konuşurlarının birbirini kısmen anlayabilmesinin nedeni nedir?', 'Üçü de aynı Kuzey Germen grubundandır.', ['Üçü de Latinceden türemiştir.', 'Üçü de Slav kolundandır.', 'Üçü de aynı alfabeyi kullanır.'], 'Ortak Eski Nors kökenli bu diller, sözcük ve dil bilgisi bakımından birbirine çok yakındır.'),
  ('Eski Kilise Slavcası, 9. yüzyılda hangi iki kardeş tarafından Kutsal Kitap çevirilerinde kullanılmak üzere düzenlenmiştir?', 'Kiril ve Metodi', ['Grimm Kardeşler', 'Wright Kardeşler', 'Marco ve Polo'], 'Selanikli kardeşler Kiril ve Metodi, Slavlar için yazı sistemi ve yazı dili oluşturmuştur; Kiril alfabesi adını ondan alır.'),
  ('Aşağıdakilerden hangisi Germen kolunun Batı Germen dallarına bir örnek değildir?', 'İsveççe', ['Almanca', 'Felemenkçe', 'İngilizce'], 'İsveççe Kuzey Germen grubundandır. Almanca, Felemenkçe ve İngilizce ise Batı Germen dilleridir.'),
  ('Latinceden ayrışan Katalanca, Portekizce ve İspanyolca hangi coğrafyada birbirinin komşusudur?', 'İber Yarımadası', ['Balkan Yarımadası', 'İskandinav Yarımadası', 'Kafkas bölgesi'], 'Bu üç Romen dili İber Yarımadası\'nda konuşulur; Latincenin burada geçirdiği gelişim kollar halinde ayrışmıştır.'),
  ('Ural dil ailesinin iki ana kolu aşağıdakilerden hangisinde doğru verilmiştir?', 'Fin-Ugor ve Samoyed', ['Oğuz ve Kıpçak kolları', 'Kuzey ve Güney Slav kolları', 'Moğol ve Tunguz kolları'], 'Ural ailesi, Fince, Macarca ve Sami gibi dilleri içeren Fin-Ugor koluyla Nenetsçe gibi Sibirya dillerini içeren Samoyed koluna ayrılır.'),
  ('Macarca, Fin-Ugor kolunun hangi dalında yer alır?', 'Ugor dalında', ['Balto-Fin dalında', 'Volga dalında', 'Samoyed dalında'], 'Macarca, Ob Irmağı çevresindeki Hantıca ve Mansiyca ile birlikte Ugor dalını oluşturur; Fince ise Balto-Fin dalındadır.'),
  ('Ad çekiminde yaklaşık on beş hâl kullanan, "evde, evden, eve" gibi kavramları ayrı ekler yoluyla anlatan dil aşağıdakilerden hangisidir?', 'Fince', ['Fransızca', 'İngilizce', 'Hollandaca'], 'Fincede iç ve dış yer hâlleri ayrı ekler alır; hâl sayısının çok olması dilin eklemeli yapısının sonucudur.'),
  ('Kazakça, Kırgızca ve Tatarca hangi Türk dil grubuna girer?', 'Kıpçak grubuna', ['Oğuz grubuna', 'Bulgar grubuna', 'Sibirya grubuna'], 'Bu diller Kıpçak Türkçesinden gelişmiş olup Orta Asya, Volga ve Kırım çevresinde konuşulur.'),
  ('Özbekçe ve Uygurca (Doğu Türkistan) hangi Türk dil grubundandır?', 'Karluk grubu', ['Oğuz grubu', 'Kıpçak grubu', 'Bulgar grubu'], 'Özbek ve Uygur dilleri, Orta Asya\'nın güneyindeki Karluk Türkçesinin devamıdır.'),
  ('Rusya\'nın Avrupa kısmında bulunan Kalmukya Cumhuriyeti\'nde konuşulan Kalmukça hangi dil grubuna aittir?', 'Moğol dilleri', ['Türk dilleri', 'Tunguz dilleri', 'Ural dilleri'], 'Kalmuklar Batı Moğol kökenli bir halktır; dilleri Moğol dilleri arasında yer alır.'),
  ('Çin\'in son hanedanı olan Qing (Mançu) hanedanının dili Mançuca hangi aileye girer?', 'Tunguz', ['Moğol dilleri', 'Türk dilleri', 'Sami dilleri'], 'Mançuca, Evenkice ve Nanayca gibi Tunguz dillerindendir; bugün çok az konuşurla sınırlıdır.'),
  ('Sibirya\'nın Evenkice, Evence ve Nanayca gibi dilleri hangi aileye girer?', 'Tunguz dilleri', ['Slav dilleri', 'Samoyed dilleri', 'Kafkas dilleri'], 'Bu diller Sibirya ve Mançurya\'da konuşulan, Mançuca ile akraba Tunguz dilleridir.'),
  ('Türk dilleri arasında en çok konuşulan dil aşağıdakilerden hangisidir?', 'Türkiye Türkçesi dili', ['Özbekçe dili', 'Kazakça dili', 'Uygurca dili'], 'Türkiye Türkçesi, ana dil olarak konuşanların sayısıyla Türk dilleri arasında en geniş kitleye sahiptir.'),
  ('Rusya\'nın Volga ve Kama ırmakları çevresinde konuşulan Udmurtça, Komice ve Mari dilleri hangi dil ailesine girer?', 'Ural ailesinin Fin-Ugor koluna', ['Türk dilleri grubunun Kıpçak koluna', 'Hint-Avrupa ailesinin Slav koluna', 'Kafkas ailesinin Kartvel koluna'], 'Udmurt, Komi ve Mari halklarının dilleri Fince ve Macarcayla akraba Fin-Ugor dilleridir; çevrelerindeki Rusça ve Tatarcadan farklı bir aileye aittir.'),
  ('Somali dili, Oromoca ve Afar dili Afro-Asya ailesinin hangi koluna girer?', 'Kuşitik kol', ['Sami kolu', 'Berberi kolu', 'Çad kolu'], 'Bu diller Afrika Boynuzu\'nda konuşulan Kuşitik kolun üyeleridir.'),
  ('Etiyopya\'da Kilise dili olarak yaşayan Geez, Amharca ve Tigrinya ile akrabadır. Bu diller Sami kolunun hangi bölgesel grubuna girer?', 'Güney (Habeş) Sami', ['Batı Sami grubu', 'Kuzeybatı Sami grubu', 'Doğu Sami grubu'], 'Etiyopya Sami dilleri, Arap Yarımadası\'nın güneyinden Afrika\'ya geçen Sami topluluklarının mirasıdır.'),
  ('Afro-Asya ailesi için hangisi doğrudur?', 'Hem Asya\'da hem Afrika\'da konuşulan diller bulunur.', ['Yalnızca Avrupa\'da konuşulan diller bulunur.', 'Yalnızca Amerika\'da konuşulan diller bulunur.', 'Yalnızca Okyanusya\'da konuşulan diller bulunur.'], 'Aile adı, Afrika ve Güneybatı Asya\'ya yayılmasından gelir; Arapça, İbranice, Amharca, Berberice ve Hausa buna örnektir.'),
  ('Batı Afrika\'da Sahel kuşağında göçebe topluluklarca yayılmış olan Fulfulde (Fula) dili hangi aileye girer?', 'Nijer-Kongo', ['Afro-Asya ailesi', 'Nil-Sahra ailesi', 'Austronezya ailesi'], 'Fula, Nijer-Kongo ailesinin Atlantik grubundadır; Senegal\'den Çad\'a kadar geniş bir alana yayılmıştır.'),
  ('Dinka (Güney Sudan), Luo ve Maasai gibi dillerin ait olduğu Nilotik kol hangi ailenin parçasıdır?', 'Nil-Sahra ailesi', ['Nijer-Kongo ailesi', 'Afro-Asya ailesi', 'Khoisan'], 'Nilotik diller, Nil Vadisi\'nde ve Doğu Afrika\'da konuşulur; Nil-Sahra ailesinin büyük bir koludur.'),
  ('Nijer-Kongo ailesinin dünya dillerinin sayısı bakımından önemi nedir?', 'Dünya dillerinin yaklaşık beşte birini kapsayan büyük bir ailedir.', ['Yalnızca üç dilden oluşan küçük bir ailedir.', 'Yalnızca Avrupa\'da konuşulan bir ailedir.', 'Yalnızca Amerika kıtasında yaygın bir ailedir.'], 'Nijer-Kongo, Bantu dillerini de kapsayarak dünyadaki en çok dil içeren ailelerden biridir.'),
  ('Etiyopya\'nın Omo Vadisi\'nde konuşulan ve Afro-Asya ailesinin kendi kolunu oluşturan dillere ne ad verilir?', 'Omotik diller', ['Bantu diller', 'Nilotik diller', 'Tunguz diller'], 'Omotik diller, Afro-Asya ailesinin Etiyopya güneyindeki bir koludur; kolun sınıflandırılması tartışmalıdır.'),
  ('Kuzey Kanada, Grönland ve Alaska\'da yaşayan İnuit ve Yupik halklarının dilleri hangi ailenin üyesidir?', 'Eskimo-Aleut ailesi', ['Na-Dene ailesi dilleri', 'Uto-Aztek ailesi dilleri', 'Algonkin ailesi dilleri'], 'Inuktitut, Yupik ve Aleut dilleri Eskimo-Aleut ailesini oluşturur; Kuzey Kutbu çevresine geniş bir alana yayılmıştır.'),
  ('Navajo ve Apaçi dilleri, Kuzey Amerika\'da hangi ailenin üyesidir?', 'Na-Dene ailesi', ['Algonkin ailesi dilleri', 'Irokua ailesi dilleri', 'Maya ailesi dilleri'], 'Navajo ve Apaçi, Kanada\'nın kuzeybatısındaki Athabaskan dillerinin güneye göç etmiş kollarıdır.'),
  ('Cree ve Ojibwe dilleri hangi ailenin üyesidir?', 'Algonkin ailesi', ['Eskimo-Aleut ailesi', 'Maya ailesi', 'Keçuva ailesi'], 'Cree ve Ojibwe, Kuzey Amerika\'nın doğusundan ve ortasından Kanada\'ya yayılan Algonkin dillerindendir.'),
  ('Mohawk ve Çeroki dilleri hangi ailenin üyesidir?', 'Irokua ailesi', ['Algonkin ailesi', 'Na-Dene ailesi', 'Uto-Aztek ailesi'], 'Irokua dilleri Büyük Göller çevresindeki Altı Millet Konfederasyonu ve güneydoğudaki Çerokiler tarafından konuşulur.'),
  ('Peru, Bolivya ve Ekvador\'da milyonlarca kişinin konuştuğu Keçuva (Quechua) dili, eskiden hangi devletin resmî iletişim dili olarak yayılmıştır?', 'İnka İmparatorluğu', ['Aztek İmparatorluğu', 'Roma İmparatorluğu', 'Osmanlı İmparatorluğu'], 'Keçuva, And Dağları\'nda kurulan İnka devletinin idari dili olarak geniş bir alana yayılmıştır.'),
  ('Paraguay\'da İspanyolca ile birlikte resmî dil olan Guarani hangi aileye girer?', 'Tupi-Guarani ailesi', ['Keçuva ailesi dilleri', 'Maya ailesi dilleri', 'Eskimo-Aleut ailesi dilleri'], 'Guarani, Güney Amerika\'nın doğusundaki Tupi-Guarani ailesinin en çok konuşulan dilidir.'),
  ('Orta Amerika\'da Guatemala ve Meksika\'da konuşulan Quiché ve Yukatek gibi diller hangi ailenin üyesidir?', 'Maya ailesi', ['Uto-Aztek ailesi', 'Irokua ailesi', 'Tupi-Guarani ailesi'], 'Maya dilleri, antik Maya uygarlığının dilinden türemiştir; bugün de yaklaşık otuz dil Maya ailesine aittir.'),
  ('Hawaii dili, Samoa dili ve Tonga dili hangi dil grubunun üyesidir?', 'Polinezya dilleri', ['Melanezya dilleri', 'Papua dilleri', 'Mikronezya dilleri'], 'Bu diller, Austronezya ailesinin Orta ve Doğu Pasifik\'e yayılan Polinezya grubundadır.'),
  ('Austronezya ailesinin anavatanı konusunda günümüzde en çok kabul gören görüş hangisidir?', 'Tayvan', ['Madagaskar', 'Avustralya', 'Yeni Zelanda'], 'Dilsel çeşitlilik ve arkeolojik veriler, ailenin Tayvan\'dan güneye ve doğuya doğru yayıldığını düşündürür.'),
  ('İngilizceye Avustralya yerli dillerinden geçen "kangaroo" sözcüğü hangi dilden gelmiştir?', 'Guugu Yimithirr', ['Maori dili', 'Hawaii dili', 'Tok Pisin dili'], '"Gangurru" sözcüğü Kuzey Queensland\'daki Guugu Yimithirr dilinde belirli bir kanguru türünü ifade eder.'),
  ('Kuzeybatı Kafkasya\'da konuşulan Abhazca ve Adıgece, hangi ses özelliğiyle dikkat çeker?', 'Çok ünsüz, az ünlü', ['Hiç ünsüz yok, yalnızca ünlü', 'Çok ünlü, az ünsüz', 'Ünlü ve ünsüz sayısı eşit'], 'Kuzeybatı Kafkas dilleri, ünlü sayısı çok az ama ünsüz sayısı çok yüksek ses sistemleriyle bilinir.'),
  ('Aşağıdaki dillerden hangisi Austronezya ailesinin üyesi olmadığı için diğerlerinden ayrılır?', 'Çeroki', ['Endonezce', 'Hawaii dili', 'Tagalog'], 'Çeroki, Kuzey Amerika\'daki Irokua ailesindendir; ötekiler Pasifik ve Güneydoğu Asya\'ya yayılmış Austronezya dilleridir.'),
  ('Pakistan\'ın kuzeyindeki Hunza Vadisi\'nde konuşulan Burushaski, bilinen hiçbir dil ailesine bağlanamaması nedeniyle hangi türden bir dil sayılır?', 'yalıtık (soyca yalnız) dil', ['pidgin', 'yapay (tasarlanmış) dil', 'ölü (konuşuru kalmamış) dil'], 'Yalıtık dil, başka hiçbir dille akrabalığı kanıtlanamayan dildir. Burushaski ve Baskça bunun tipik örnekleridir.'),
  ('Latince konuşan Romalılar Galya\'ya yerleştiğinde, yerli Gall (Kelt) dilinin Fransızcada bıraktığı iz dil biliminde hangi adla anılır?', 'alt katman (substrat) etkisi', ['üst katman (superstrat) etkisi', 'ödünçleme (alıntılama) olayı', 'dilsel yalıtım olayı'], 'Yerli halkın dilinin, yeni gelen baskın dili etkilemesi substrat etkisidir.'),
  ('Dil birliği kavramı için aşağıdakilerden hangisi doğrudur?', 'Akraba olmayan komşu dillerin ortak özellik kazanması', ['Bütün dillerin aynı ses sistemini taşıması', 'Bir dilin yalnızca yazıyla kaydedilmesi', 'İki dilin aynı ata dilden türemesi'], 'Dil birliğinde dillerin özellikleri temasla yakınlaşır; bu soy akrabalığından bağımsızdır.'),
  ('Tek bir aileye bağlanamayan ve yalıtık olarak kabul edilen aşağıdaki dillerden hangisi bugün canlıdır?', 'Baskça', ['Sümerce', 'Etrüskçe', 'Hititçe'], 'Baskça İspanya ve Fransa sınırındaki Basklar tarafından bugün de konuşulur; Sümerce ve Etrüskçe ölü dillerdir, Hititçe ise Hint-Avrupa ailesindedir.'),
  ('Almancada isimlerin eril, dişil ve yansız olmak üzere üç dil bilgisel cinsiyeti vardır. Aşağıdakilerden hangisinde dil bilgisel cinsiyet bulunmaz?', 'İngilizce (adlarda)', ['Fransızca (adlarda)', 'Rusça (adlarda)', 'İspanyolca (adlarda)'], 'İngilizcede isimler cinsiyet ayrımı yapmaz; yalnızca zamirlerde he/she/it ayrımı vardır.'),
  ('Dil bilimin hangi dalı, sözcüklerin iç yapısını ve biçimbirimlerin birleşme kurallarını inceler?', 'biçim bilgisi', ['sözdizim (söz dizimi) dalı', 'ses bilgisi (fonoloji) dalı', 'edim bilim (pragmatik) dalı'], 'Biçim bilgisi, en küçük anlamlı birimler olan biçimbirimlerin sözcük oluşturmak üzere nasıl birleştiğini inceler.'),
  ('Dil bilimin hangi dalı, sözcüklerin öbek ve cümle kurmak için nasıl dizildiğini inceler?', 'sözdizim', ['biçim bilgisi', 'ses bilgisi', 'anlam bilim'], 'Sözdizim, sözcüklerin öbek ve tümce oluşturmak üzere bir araya gelme kurallarıyla ilgilenir.'),
  ('Hockett\'in tasarım özelliklerinden "keyfîlik" için hangisi doğrudur?', 'Sözcüğün sesiyle anlamı arasında zorunlu bağ yoktur.', ['Sözcüğün anlamı yalnızca sesine bağlıdır.', 'Dillerde hiçbir yansıma sözcük yoktur.', 'Bütün dillerdeki sözcükler birbirine benzer.'], 'Keyfîlik, Saussure\'ün nedensizlik ilkesinin karşılığıdır: aynı kavram farklı dillerde farklı seslerle ifade edilir.'),
  ('Bir konuşurun aynı konuşma içinde iki dil arasında geçiş yapmasına (örneğin Türkçe cümlenin ortasında İngilizce sözcük kullanması) ne ad verilir?', 'kod değiştirme', ['dil ölümü olayı', 'ses benzeşmesi olayı', 'yan anlam olayı'], 'Kod değiştirme, iki dilli konuşurların bağlama göre dil çeşitleri arasında geçiş yapmasıdır.'),
  ('Dil ve yazı arasındaki ilişki için aşağıdakilerden hangisi doğrudur?', 'Yazı dilin kaydıdır; dil yazıdan öncedir, yazısız da yaşar.', ['Yazısı olmayan bir dil, gerçek dil sayılmaz.', 'Yazı ile dil tamamen aynı şeydir.', 'Dil, yazının icadıyla birlikte doğmuştur.'], 'Dil bilimi konuşulan dili temel alır; birçok dilin yazısı yoktur, ancak hepsi tam anlamıyla dildir.'),
  ('Bir sözcüğün bağlamsız olarak sözlükteki karşılığı ile cümle içinde kazandığı anlam arasındaki farkı inceleyen yaklaşım hangisidir?', 'anlam bilim–edim bilim ayrımı', ['ses bilgisi–biçim bilgisi ayrımı', 'eşzamanlı–artzamanlı dil ayrımı', 'betimleyici–kural koyucu ayrımı'], 'Sözcük anlamı anlam bilimin, bağlam içindeki yorum edim biliminin konusudur.'),
  ('Bir yabancı dil öğrencisinin "yağmur yağmak" yerine "yağmur dökülmek" demesi, hangi tür dil bilgisi sorunu olarak değerlendirilebilir?', 'bağdaşma (kolokasyon) sorunu', ['ses bilgisi (fonetik) sorunu', 'yazım (imla) sorunu', 'ek kullanımı (biçim bilgisi) sorunu'], 'Sözcükler anlamca uyumlu görünse de birlikte kullanılma alışkanlıkları dile özgüdür.'),
  ('Altı ay civarındaki bebeklerin "ba-ba-ba" ya da "ma-ma-ma" gibi anlamsız hece dizileri çıkarması dil edinimi araştırmalarında hangi aşama olarak adlandırılır?', 'gevezelik (babbling) evresi', ['ilk sözcük evresi', 'iki sözcüklü evre', 'kural aşırı genelleme evresi'], 'Gevezelik evresi, bebeğin konuşma seslerini üretmeyi denediği, henüz anlam taşımayan seslendirme evresidir.'),
  ('Aşağıdaki ünsüzlerden hangisi "süreksiz" (hava akımını bir an tamamen kesen) bir sestir?', '[t]', ['[s]', '[f]', '[z]'], '[t] patlamalı olduğu için havayı bir an tamamen keser. [s], [f], [z] sürtünmeli olduğundan hava akımı sürer.'),
  ('Dünyada anadil olarak en çok konuşulan dil hangisidir?', 'Mandarin Çincesi', ['İngilizce dili', 'İspanyolca dili', 'Hintçe dili'], 'Mandarin Çincesi, anadil konuşuru sayısında yıllardır birinci sıradadır.'),
  ('Yetişkinlerin küçük çocuklara yavaş, yüksek perdeli ve basit konuştuğu söz biçimine ne ad verilir?', 'bakıcı konuşması', ['telgrafik konuşma', 'gevezelik', 'kod değiştirme'], 'Bakıcı konuşması, çocuğun dil edinimini kolaylaştırdığı düşünülen sade ve ezgili bir konuşma biçimidir.'),
  ('Sağ elini kullanan kişilerin büyük çoğunluğunda dil işlevlerinin ağırlıklı olarak hangi beyin yarıküresinde yer aldığı kabul edilir?', 'sol yarıküre', ['sağ yarıküre', 'beyincik', 'omurilik soğanı'], 'Dil üretimi ve anlaşılması çoğu kişide sol yarıküredeki Broca ve Wernicke alanlarıyla ilişkilidir.'),
  ('Sözlük hazırlama ilkelerini ve sözcüklerin sözlükte nasıl düzenleneceğini inceleyen dal hangisidir?', 'sözlükbilim', ['sesbilim', 'anlambilim', 'yazı bilim'], 'Sözlükbilim (leksikografi), sözlük yapımı ve ilkelerini ele alır.'),
  ('Dil biliminde "bilgisayarlı dil bilimi" nedir?', 'Dilin işlenmesini bilgisayar yöntemleriyle inceleyen alan', ['Yalnızca bilgisayar dillerinin kuralları', 'Yazı makinesi tarihçesinin incelenmesi', 'Ses kayıt cihazlarının üretilmesi'], 'Bilgisayarlı dil bilimi, otomatik çeviri, metin çözümleme ve konuşma tanıma gibi uygulamaları kapsar.'),
  ('Bir dili tarihsel sürecinden bağımsız olarak, belirli bir dönemdeki durumuyla incelemeye ne ad verilir?', 'eşzamanlı (sinkronik) inceleme', ['artzamanlı (diyakronik) inceleme', 'karşılaştırmalı (komparatif) inceleme', 'dil planlaması çalışması'], 'Eşzamanlı inceleme, dilin belirli bir zaman kesitindeki yapısını ele alır; tarihî gelişim incelemesi artzamanlıdır.'),
  ('"Ahmet\'in kardeşi hastalandı." cümlesinin ön varsayımı aşağıdakilerden hangisidir?', 'Ahmet\'in bir kardeşi vardır.', ['Ahmet de hastadır.', 'Ahmet\'in yalnızca bir kardeşi vardır.', 'Ahmet\'in kardeşi doktora gitmiştir.'], 'İyelik yapısı, sahibin böyle bir varlığa sahip olduğunu ön varsayar; cümle olumsuz olsa da bu bilgi sürer.'),
  ('"Buraya gel." ve "Oraya git." buyruklarının farkını anlamak için hangi bilgiye ihtiyaç vardır?', 'Konuşurun bulunduğu yer', ['Konuşurun yaşı', 'Dinleyicinin mesleği', 'Cümlenin yazıldığı kâğıt'], 'Yer gösteriminin anlamı, konuşurun bulunduğu yere göre belirlenir.'),
  ('"Özür dilerim." cümlesi Searle\'ün sınıflandırmasında hangi tür söz eylemdir?', 'duygu bildiren', ['bağlayıcı olan', 'yönlendirici olan', 'bildirge olan'], 'Özür dileme, konuşurun kendi davranışına ilişkin duygusunu bildirdiği için duygu bildirenler grubundadır.'),
